// Generated by Nemo — recreates the camera move as a real, editable
// After Effects camera. Run from After Effects: File > Scripts > Run Script File…
// (with a composition open/selected) — or drop this file into the
// ScriptUI Panels folder to run it from the Window menu instead.
(function(){
  var comp = app.project.activeItem;
  if (!(comp && comp instanceof CompItem)) {
    alert("Ouvre ou sélectionne une composition dans After Effects, puis relance ce script.");
    return;
  }
  app.beginUndoGroup("Import caméra Nemo");
  try {
    var cam = comp.layers.addCamera("Nemo Camera", [comp.width/2, comp.height/2]);
    cam.property("Camera Options").property("Zoom").setValue(1920);
    var poi = cam.property("Transform").property("Point of Interest");
    var pos = cam.property("Transform").property("Position");
    var rotZ = cam.property("Transform").property("Z Rotation");
    var times = [0];
    poi.setValuesAtTimes(times, [[960,540,0]]);
    pos.setValuesAtTimes(times, [[960,540,-1920]]);
    rotZ.setValuesAtTimes(times, [0]);
    for (var i = 1; i <= poi.numKeys; i++) poi.setInterpolationTypeAtKey(i, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    for (var i = 1; i <= pos.numKeys; i++) pos.setInterpolationTypeAtKey(i, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    for (var i = 1; i <= rotZ.numKeys; i++) rotZ.setInterpolationTypeAtKey(i, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    alert("Caméra Nemo importée : " + times.length + " image(s)-clé.");
  } catch (e) {
    alert("Échec de l'import caméra : " + e.toString());
  }
  app.endUndoGroup();
})();

